private void normalizeColumnNames(){
  Preconditions.checkNotNull(includes);
  try {
    normalizeColumnNames(includes);
  } catch (IndexOutOfBoundsException | ClassCastException | NullPointerException e) {
    e.printStackTrace();
  }
  Preconditions.checkNotNull(selectRule.mandatoryDims);
  try {
    normalizeColumnNames(selectRule.mandatoryDims);
  } catch (IndexOutOfBoundsException | ClassCastException | NullPointerException e) {
    e.printStackTrace();
  }
  if (selectRule.hierarchyDims == null)   selectRule.hierarchyDims=new String[0][];
  for (  String[] cols : selectRule.hierarchyDims) {
    Preconditions.checkNotNull(cols);
    try {
      normalizeColumnNames(cols);
    } catch (IndexOutOfBoundsException | ClassCastException | NullPointerException e) {
      e.printStackTrace();
    }
  }
  if (selectRule.jointDims == null)   selectRule.jointDims=new String[0][];
